"use client"

import { useEffect, useState } from "react"
import Link from "next/link"
import { api, AvailableTool, Tool } from "@/lib/api"
import { Button } from "@/components/ui/button"
import { Switch } from "@/components/ui/switch"
import { Separator } from "@/components/ui/separator"
import { Label } from "@/components/ui/label"
import { Loader2, ArrowLeft, Mail, Calendar, FileText, Plug, ExternalLink } from "lucide-react"

const toolIcons: Record<string, React.ReactNode> = {
  gmail: <Mail className="h-5 w-5" />,
  googlecalendar: <Calendar className="h-5 w-5" />,
  googledocs: <FileText className="h-5 w-5" />,
}

export default function IntegrationsPage() {
  const [available, setAvailable] = useState<AvailableTool[]>([])
  const [connected, setConnected] = useState<Tool[]>([])
  const [triggerStatus, setTriggerStatus] = useState(false)
  const [loading, setLoading] = useState<string | null>(null)
  const [error, setError] = useState("")

  useEffect(() => {
    loadData()
  }, [])

  const loadData = async () => {
    const [availRes, connRes, trigRes] = await Promise.all([
      api.getAvailableTools(),
      api.getConnectedTools(),
      api.getTriggerStatus(),
    ])
    if (availRes.ok) setAvailable((await availRes.json()).toolkits || [])
    if (connRes.ok) setConnected((await connRes.json()).tools || [])
    if (trigRes.ok) setTriggerStatus((await trigRes.json()).configured)
  }

  const isConnected = (toolkit: string) => connected.some((t) => t.toolkit === toolkit)

  const toggleConnection = async (toolkit: string) => {
    setLoading(toolkit)
    setError("")
    
    if (isConnected(toolkit)) {
      await api.disconnectTool(toolkit)
    } else {
      const res = await api.connectTool(toolkit)
      if (res.ok) {
        const data = await res.json()
        if (data.redirect_url) {
          window.open(data.redirect_url, "_blank", "width=600,height=700")
        }
      } else {
        const data = await res.json()
        setError(data.detail || "Failed to connect")
      }
    }
    
    setLoading(null)
    setTimeout(loadData, 2000)
  }

  const setupTrigger = async () => {
    setLoading("trigger")
    const res = await api.setupGmailTrigger()
    setLoading(null)
    if (res.ok) setTriggerStatus(true)
    else setError("Failed to setup trigger")
  }

  return (
    <div className="max-w-xl">
      <div className="mb-6">
        <Link href="/dashboard" className="inline-flex items-center text-sm text-muted-foreground hover:text-foreground mb-4">
          <ArrowLeft className="mr-2 h-4 w-4" />
          Settings
        </Link>
        <h1 className="text-2xl font-semibold tracking-tight">Integrations</h1>
        <p className="text-muted-foreground">Connect services to extend your agent's capabilities</p>
      </div>

      {error && (
        <div className="mb-4 rounded-md bg-destructive/10 px-4 py-3 text-sm text-destructive">
          {error}
        </div>
      )}

      <Separator className="my-6" />

      <div className="space-y-6">
        <div>
          <h2 className="text-sm font-medium text-muted-foreground mb-4">Notifications</h2>
          <div className="flex items-center justify-between rounded-lg border p-4">
            <div className="flex items-center gap-4">
              <div className="flex h-10 w-10 items-center justify-center rounded-lg border bg-background">
                <Mail className="h-5 w-5 text-primary" />
              </div>
              <div>
                <p className="font-medium">Gmail notifications</p>
                <p className="text-sm text-muted-foreground">Get notified about new emails via WhatsApp</p>
              </div>
            </div>
            <Switch
              checked={triggerStatus}
              onCheckedChange={setupTrigger}
              disabled={loading === "trigger" || triggerStatus}
            />
          </div>
        </div>

        <div>
          <h2 className="text-sm font-medium text-muted-foreground mb-4">Connected accounts</h2>
          <div className="space-y-2">
            {available.length === 0 ? (
              <p className="text-sm text-muted-foreground py-4">Loading...</p>
            ) : (
              available.map((tool) => (
                <div key={tool.name} className="flex items-center justify-between rounded-lg border p-4">
                  <div className="flex items-center gap-4">
                    <div className="flex h-10 w-10 items-center justify-center rounded-lg border bg-background">
                      {toolIcons[tool.name.toLowerCase()] || <Plug className="h-5 w-5 text-primary" />}
                    </div>
                    <div>
                      <p className="font-medium">{tool.label || tool.name}</p>
                      <p className="text-sm text-muted-foreground">
                        {isConnected(tool.name) ? "Connected" : "Not connected"}
                      </p>
                    </div>
                  </div>
                  <Button
                    variant={isConnected(tool.name) ? "outline" : "default"}
                    size="sm"
                    onClick={() => toggleConnection(tool.name)}
                    disabled={loading === tool.name}
                  >
                    {loading === tool.name && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                    {isConnected(tool.name) ? "Disconnect" : "Connect"}
                  </Button>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  )
}

"use client"

import { useEffect, useState } from "react"
import Link from "next/link"
import { api, Memory } from "@/lib/api"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Label } from "@/components/ui/label"
import { Separator } from "@/components/ui/separator"
import { ArrowLeft, Search, Trash2, Loader2, MoreHorizontal } from "lucide-react"
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"

export default function MemoryPage() {
  const [memories, setMemories] = useState<Memory[]>([])
  const [search, setSearch] = useState("")
  const [newMemory, setNewMemory] = useState("")
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState("")

  useEffect(() => {
    loadMemories()
  }, [])

  const loadMemories = async () => {
    const res = await api.getMemories()
    if (res.ok) {
      const data = await res.json()
      setMemories(data.memories || [])
    }
  }

  const searchMemories = async () => {
    if (!search.trim()) {
      loadMemories()
      return
    }
    setLoading(true)
    const res = await api.searchMemories(search)
    setLoading(false)
    if (res.ok) {
      const data = await res.json()
      setMemories(data.memories || [])
    }
  }

  const addMemory = async () => {
    if (!newMemory.trim()) return
    setLoading(true)
    setError("")
    const res = await api.addMemory(newMemory)
    setLoading(false)
    if (res.ok) {
      setNewMemory("")
      loadMemories()
    } else {
      setError("Failed to add memory")
    }
  }

  const deleteMemory = async (id: string) => {
    await api.deleteMemory(id)
    loadMemories()
  }

  const clearAll = async () => {
    setLoading(true)
    await api.clearMemories()
    setLoading(false)
    setMemories([])
  }

  return (
    <div className="max-w-2xl">
      <div className="mb-6">
        <Link href="/dashboard" className="inline-flex items-center text-sm text-muted-foreground hover:text-foreground mb-4">
          <ArrowLeft className="mr-2 h-4 w-4" />
          Settings
        </Link>
        <h1 className="text-2xl font-semibold tracking-tight">Memory</h1>
        <p className="text-muted-foreground">View and manage what your AI agent remembers</p>
      </div>

      {error && (
        <div className="mb-4 rounded-md bg-destructive/10 px-4 py-3 text-sm text-destructive">
          {error}
        </div>
      )}

      <Separator className="my-6" />

      <div className="space-y-6">
        <div className="space-y-2">
          <Label>Add memory</Label>
          <Textarea
            placeholder="e.g., My favorite color is blue, I prefer morning meetings..."
            value={newMemory}
            onChange={(e) => setNewMemory(e.target.value)}
            rows={2}
          />
          <Button onClick={addMemory} disabled={loading || !newMemory.trim()} size="sm">
            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Add
          </Button>
        </div>

        <Separator />

        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <Label>Stored memories ({memories.length})</Label>
            {memories.length > 0 && (
              <AlertDialog>
                <AlertDialogTrigger asChild>
                  <Button variant="ghost" size="sm" className="text-muted-foreground">
                    Clear all
                  </Button>
                </AlertDialogTrigger>
                <AlertDialogContent>
                  <AlertDialogHeader>
                    <AlertDialogTitle>Clear all memories?</AlertDialogTitle>
                    <AlertDialogDescription>
                      This will permanently delete all stored memories. This cannot be undone.
                    </AlertDialogDescription>
                  </AlertDialogHeader>
                  <AlertDialogFooter>
                    <AlertDialogCancel>Cancel</AlertDialogCancel>
                    <AlertDialogAction onClick={clearAll}>Delete all</AlertDialogAction>
                  </AlertDialogFooter>
                </AlertDialogContent>
              </AlertDialog>
            )}
          </div>

          <div className="flex gap-2">
            <Input
              placeholder="Search memories..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && searchMemories()}
            />
            <Button variant="outline" size="icon" onClick={searchMemories}>
              <Search className="h-4 w-4" />
            </Button>
          </div>

          {memories.length === 0 ? (
            <p className="text-sm text-muted-foreground py-8 text-center">
              No memories yet. Your agent learns from conversations.
            </p>
          ) : (
            <div className="rounded-lg border divide-y">
              {memories.map((memory) => (
                <div key={memory.id} className="flex items-start justify-between p-4">
                  <div className="flex-1 min-w-0">
                    <p className="text-sm">{memory.memory || memory.text}</p>
                    {memory.created_at && (
                      <p className="text-xs text-muted-foreground mt-1">
                        {new Date(memory.created_at).toLocaleDateString()}
                      </p>
                    )}
                  </div>
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button variant="ghost" size="icon" className="h-8 w-8">
                        <MoreHorizontal className="h-4 w-4" />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end">
                      <DropdownMenuItem onClick={() => deleteMemory(memory.id)} className="text-destructive">
                        <Trash2 className="mr-2 h-4 w-4" />
                        Delete
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

"use client"

import { useEffect, useState } from "react"
import { api, LinkingStatus } from "@/lib/api"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { InputOTP, InputOTPGroup, InputOTPSlot } from "@/components/ui/input-otp"
import { Separator } from "@/components/ui/separator"
import { Loader2, ArrowLeft } from "lucide-react"
import Link from "next/link"

export default function WhatsAppPage() {
  const [status, setStatus] = useState<LinkingStatus | null>(null)
  const [phone, setPhone] = useState("")
  const [otp, setOtp] = useState("")
  const [step, setStep] = useState<"idle" | "otp">("idle")
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState("")

  useEffect(() => {
    loadStatus()
  }, [])

  const loadStatus = async () => {
    const res = await api.getLinkingStatus()
    if (res.ok) setStatus(await res.json())
  }

  const sendOTP = async () => {
    setLoading(true)
    setError("")
    const res = await api.sendOTP(phone)
    setLoading(false)
    if (res.ok) {
      setStep("otp")
    } else {
      const data = await res.json()
      setError(data.detail || "Failed to send OTP")
    }
  }

  const verifyOTP = async () => {
    setLoading(true)
    setError("")
    const res = await api.verifyOTP(phone, otp)
    setLoading(false)
    if (res.ok) {
      setStep("idle")
      setPhone("")
      setOtp("")
      loadStatus()
    } else {
      const data = await res.json()
      setError(data.detail || "Invalid OTP")
    }
  }

  const unlink = async () => {
    setLoading(true)
    await api.unlinkWhatsApp()
    setLoading(false)
    loadStatus()
  }

  return (
    <div className="max-w-xl">
      <div className="mb-6">
        <Link href="/dashboard" className="inline-flex items-center text-sm text-muted-foreground hover:text-foreground mb-4">
          <ArrowLeft className="mr-2 h-4 w-4" />
          Settings
        </Link>
        <h1 className="text-2xl font-semibold tracking-tight">WhatsApp</h1>
        <p className="text-muted-foreground">Link your WhatsApp number to chat with your AI agent</p>
      </div>

      <Separator className="my-6" />

      {error && (
        <div className="mb-4 rounded-md bg-destructive/10 px-4 py-3 text-sm text-destructive">
          {error}
        </div>
      )}

      {status?.linked ? (
        <div className="space-y-6">
          <div>
            <Label className="text-muted-foreground">Phone number</Label>
            <p className="text-lg font-medium mt-1">{status.phone_number}</p>
            {status.linked_at && (
              <p className="text-sm text-muted-foreground mt-1">
                Linked on {new Date(status.linked_at).toLocaleDateString()}
              </p>
            )}
          </div>
          <Button variant="outline" onClick={unlink} disabled={loading}>
            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Unlink
          </Button>
        </div>
      ) : step === "idle" ? (
        <div className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="phone">Phone number</Label>
            <p className="text-sm text-muted-foreground">
              Enter your phone number with country code (e.g., 919876543210)
            </p>
            <Input
              id="phone"
              placeholder="919876543210"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
            />
          </div>
          <Button onClick={sendOTP} disabled={loading || !phone}>
            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Send verification code
          </Button>
        </div>
      ) : (
        <div className="space-y-4">
          <div className="space-y-2">
            <Label>Verification code</Label>
            <p className="text-sm text-muted-foreground">
              Enter the 6-digit code sent to your WhatsApp
            </p>
            <InputOTP maxLength={6} value={otp} onChange={setOtp}>
              <InputOTPGroup>
                <InputOTPSlot index={0} />
                <InputOTPSlot index={1} />
                <InputOTPSlot index={2} />
                <InputOTPSlot index={3} />
                <InputOTPSlot index={4} />
                <InputOTPSlot index={5} />
              </InputOTPGroup>
            </InputOTP>
          </div>
          <div className="flex gap-2">
            <Button onClick={verifyOTP} disabled={loading || otp.length !== 6}>
              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Verify
            </Button>
            <Button variant="ghost" onClick={() => { setStep("idle"); setOtp(""); setError("") }}>
              Cancel
            </Button>
          </div>
        </div>
      )}
    </div>
  )
}

"use client"

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { cva, type VariantProps } from "class-variance-authority"
import { PanelLeftIcon } from "lucide-react"

import { useIsMobile } from "@/hooks/use-mobile"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Separator } from "@/components/ui/separator"
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet"
import { Skeleton } from "@/components/ui/skeleton"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"

const SIDEBAR_COOKIE_NAME = "sidebar_state"
const SIDEBAR_COOKIE_MAX_AGE = 60 * 60 * 24 * 7
const SIDEBAR_WIDTH = "16rem"
const SIDEBAR_WIDTH_MOBILE = "18rem"
const SIDEBAR_WIDTH_ICON = "3rem"
const SIDEBAR_KEYBOARD_SHORTCUT = "b"

type SidebarContextProps = {
  state: "expanded" | "collapsed"
  open: boolean
  setOpen: (open: boolean) => void
  openMobile: boolean
  setOpenMobile: (open: boolean) => void
  isMobile: boolean
  toggleSidebar: () => void
}

const SidebarContext = React.createContext<SidebarContextProps | null>(null)

function useSidebar() {
  const context = React.useContext(SidebarContext)
  if (!context) {
    throw new Error("useSidebar must be used within a SidebarProvider.")
  }

  return context
}

function SidebarProvider({
  defaultOpen = true,
  open: openProp,
  onOpenChange: setOpenProp,
  className,
  style,
  children,
  ...props
}: React.ComponentProps<"div"> & {
  defaultOpen?: boolean
  open?: boolean
  onOpenChange?: (open: boolean) => void
}) {
  const isMobile = useIsMobile()
  const [openMobile, setOpenMobile] = React.useState(false)

  // This is the internal state of the sidebar.
  // We use openProp and setOpenProp for control from outside the component.
  const [_open, _setOpen] = React.useState(defaultOpen)
  const open = openProp ?? _open
  const setOpen = React.useCallback(
    (value: boolean | ((value: boolean) => boolean)) => {
      const openState = typeof value === "function" ? value(open) : value
      if (setOpenProp) {
        setOpenProp(openState)
      } else {
        _setOpen(openState)
      }

      // This sets the cookie to keep the sidebar state.
      document.cookie = `${SIDEBAR_COOKIE_NAME}=${openState}; path=/; max-age=${SIDEBAR_COOKIE_MAX_AGE}`
    },
    [setOpenProp, open]
  )

  // Helper to toggle the sidebar.
  const toggleSidebar = React.useCallback(() => {
    return isMobile ? setOpenMobile((open) => !open) : setOpen((open) => !open)
  }, [isMobile, setOpen, setOpenMobile])

  // Adds a keyboard shortcut to toggle the sidebar.
  React.useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (
        event.key === SIDEBAR_KEYBOARD_SHORTCUT &&
        (event.metaKey || event.ctrlKey)
      ) {
        event.preventDefault()
        toggleSidebar()
      }
    }

    window.addEventListener("keydown", handleKeyDown)
    return () => window.removeEventListener("keydown", handleKeyDown)
  }, [toggleSidebar])

  // We add a state so that we can do data-state="expanded" or "collapsed".
  // This makes it easier to style the sidebar with Tailwind classes.
  const state = open ? "expanded" : "collapsed"

  const contextValue = React.useMemo<SidebarContextProps>(
    () => ({
      state,
      open,
      setOpen,
      isMobile,
      openMobile,
      setOpenMobile,
      toggleSidebar,
    }),
    [state, open, setOpen, isMobile, openMobile, setOpenMobile, toggleSidebar]
  )

  return (
    <SidebarContext.Provider value={contextValue}>
      <TooltipProvider delayDuration={0}>
        <div
          data-slot="sidebar-wrapper"
          style={
            {
              "--sidebar-width": SIDEBAR_WIDTH,
              "--sidebar-width-icon": SIDEBAR_WIDTH_ICON,
              ...style,
            } as React.CSSProperties
          }
          className={cn(
            "group/sidebar-wrapper has-data-[variant=inset]:bg-sidebar flex min-h-svh w-full",
            className
          )}
          {...props}
        >
          {children}
        </div>
      </TooltipProvider>
    </SidebarContext.Provider>
  )
}

function Sidebar({
  side = "left",
  variant = "sidebar",
  collapsible = "offcanvas",
  className,
  children,
  ...props
}: React.ComponentProps<"div"> & {
  side?: "left" | "right"
  variant?: "sidebar" | "floating" | "inset"
  collapsible?: "offcanvas" | "icon" | "none"
}) {
  const { isMobile, state, openMobile, setOpenMobile } = useSidebar()

  if (collapsible === "none") {
    return (
      <div
        data-slot="sidebar"
        className={cn(
          "bg-sidebar text-sidebar-foreground flex h-full w-(--sidebar-width) flex-col",
          className
        )}
        {...props}
      >
        {children}
      </div>
    )
  }

  if (isMobile) {
    return (
      <Sheet open={openMobile} onOpenChange={setOpenMobile} {...props}>
        <SheetContent
          data-sidebar="sidebar"
          data-slot="sidebar"
          data-mobile="true"
          className="bg-sidebar text-sidebar-foreground w-(--sidebar-width) p-0 [&>button]:hidden"
          style={
            {
              "--sidebar-width": SIDEBAR_WIDTH_MOBILE,
            } as React.CSSProperties
          }
          side={side}
        >
          <SheetHeader className="sr-only">
            <SheetTitle>Sidebar</SheetTitle>
            <SheetDescription>Displays the mobile sidebar.</SheetDescription>
          </SheetHeader>
          <div className="flex h-full w-full flex-col">{children}</div>
        </SheetContent>
      </Sheet>
    )
  }

  return (
    <div
      className="group peer text-sidebar-foreground hidden md:block"
      data-state={state}
      data-collapsible={state === "collapsed" ? collapsible : ""}
      data-variant={variant}
      data-side={side}
      data-slot="sidebar"
    >
      {/* This is what handles the sidebar gap on desktop */}
      <div
        data-slot="sidebar-gap"
        className={cn(
          "relative w-(--sidebar-width) bg-transparent transition-[width] duration-200 ease-linear",
          "group-data-[collapsible=offcanvas]:w-0",
          "group-data-[side=right]:rotate-180",
          variant === "floating" || variant === "inset"
            ? "group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+(--spacing(4)))]"
            : "group-data-[collapsible=icon]:w-(--sidebar-width-icon)"
        )}
      />
      <div
        data-slot="sidebar-container"
        className={cn(
          "fixed inset-y-0 z-10 hidden h-svh w-(--sidebar-width) transition-[left,right,width] duration-200 ease-linear md:flex",
          side === "left"
            ? "left-0 group-data-[collapsible=offcanvas]:left-[calc(var(--sidebar-width)*-1)]"
            : "right-0 group-data-[collapsible=offcanvas]:right-[calc(var(--sidebar-width)*-1)]",
          // Adjust the padding for floating and inset variants.
          variant === "floating" || variant === "inset"
            ? "p-2 group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+(--spacing(4))+2px)]"
            : "group-data-[collapsible=icon]:w-(--sidebar-width-icon) group-data-[side=left]:border-r group-data-[side=right]:border-l",
          className
        )}
        {...props}
      >
        <div
          data-sidebar="sidebar"
          data-slot="sidebar-inner"
          className="bg-sidebar group-data-[variant=floating]:border-sidebar-border flex h-full w-full flex-col group-data-[variant=floating]:rounded-lg group-data-[variant=floating]:border group-data-[variant=floating]:shadow-sm"
        >
          {children}
        </div>
      </div>
    </div>
  )
}

function SidebarTrigger({
  className,
  onClick,
  ...props
}: React.ComponentProps<typeof Button>) {
  const { toggleSidebar } = useSidebar()

  return (
    <Button
      data-sidebar="trigger"
      data-slot="sidebar-trigger"
      variant="ghost"
      size="icon"
      className={cn("size-7", className)}
      onClick={(event) => {
        onClick?.(event)
        toggleSidebar()
      }}
      {...props}
    >
      <PanelLeftIcon />
      <span className="sr-only">Toggle Sidebar</span>
